const DOT_SEPARATORS = new Set(['.', '\u3002', '\uFF0E', '\uFF61']);

function toInputString(value) {
  return typeof value === 'string' ? value : bytesToAscii(value);
}

function splitDomain(domain) {
  if (domain.length === 0) {
    throw new IDNAError('Empty domain');
  }

  const normalized = Array.from(domain, (character) => (DOT_SEPARATORS.has(character) ? '.' : character)).join('');
  const trailingDot = normalized.endsWith('.');
  const body = trailingDot ? normalized.slice(0, -1) : normalized;

  if (body.length === 0) {
    if (trailingDot) {
      throw new IDNAError('Empty Label');
    }

    throw new IDNAError('Empty domain');
  }

  const labels = body.split('.');

  if (labels.some((label) => label.length === 0)) {
    throw new IDNAError('Empty Label');
  }

  return { labels, trailingDot };
}

function decodeALabel(label) {
  if (label.length === 4) {
    throw new IDNAError('Malformed A-label, no Punycode eligible content found');
  }

  let decoded;

  try {
    decoded = decodePunycode(label.slice(4));
  } catch (error) {
    if (error instanceof PunycodeError) {
      throw new IDNAError('Invalid A-label');
    }

    throw error;
  }

  validateUnicodeLabel(decoded);

