  if (recoded.toLowerCase() !== label.toLowerCase()) {
    throw new IDNAError('Invalid A-label');
  }

  ensureLabelLength(recoded);
  return decoded;
}

function isALabel(label) {
  return /^xn--/i.test(label);
}

export function alabel(label) {
  const input = toInputString(label);

  if (!hasNonAscii(input)) {
    if (isALabel(input)) {
      decodeALabel(input);
      ensureLabelLength(input);
      return asciiToBytes(input);
    }

    validateAsciiLabel(input);
    return asciiToBytes(input);
  }

  validateUnicodeLabel(input);
  const encoded = `xn--${encodePunycode(input)}`;
  ensureLabelLength(encoded);
  return asciiToBytes(encoded);
}

export function ulabel(label) {
  const input = toInputString(label);

  if (!hasNonAscii(input)) {
    if (isALabel(input)) {
      return decodeALabel(input);
    }

    validateAsciiLabel(input);
    return input.toLowerCase();
  }

  validateUnicodeLabel(input);
  return input;
}

export function encode(domain) {
  const { labels, trailingDot } = splitDomain(toInputString(domain));
