function basename(pathname) {
  if (!pathname) {
    return 'test1.mjs';
  }

  const normalized = pathname.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] || 'test1.mjs';
}

function usage(programName) {
  return `usage: ${programName} [-h] --domain DOMAIN`;
}

function help(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help       show this help message and exit\n  --domain DOMAIN`;
}

function isValueToken(token) {
  return token !== undefined && token !== '--' && (token === '-' || !token.startsWith('-'));
}

function writeAndExit(message, code, stream = process.stderr) {
  stream.write(`${message}\n`);
  process.exit(code);
}

export function getProgramName(argv = process.argv) {
  return basename(argv[1]);
}

export function parseArgs(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  let domain;
  let endOfOptions = false;
  const unknown = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (!endOfOptions && (token === '-h' || token === '--help')) {
      writeAndExit(help(programName), 0, process.stdout);
    }

    if (!endOfOptions && token === '--') {
      endOfOptions = true;
      continue;
    }

    if (!endOfOptions && token === '--domain') {
      const value = tokens[index + 1];

      if (!isValueToken(value)) {
        writeAndExit(
          `${usage(programName)}\n${programName}: error: argument --domain: expected one argument`,
          2,
        );
      }

      domain = value;
      index += 1;
      continue;
    }

    if (!endOfOptions && token.startsWith('--domain=')) {
      domain = token.slice('--domain='.length);
      continue;
    }

    unknown.push(token);
  }

  if (domain === undefined) {
    writeAndExit(
      `${usage(programName)}\n${programName}: error: the following arguments are required: --domain`,
      2,
    );
  }

  if (unknown.length > 0) {
    writeAndExit(
      `${usage(programName)}\n${programName}: error: unrecognized arguments: ${unknown.join(' ')}`,
      2,
    );
  }

  return { domain };
}

